}
public sealed class Crack : PicoGK.IImplicit
{
private readonly Vector3 centre;
private readonly float half;
private readonly float gap;
private readonly float close;
public Crack(Vector3 centre, float half, float gap, float close) { this.centre=centre; this.half=half; this.gap=gap; this.close=close; }
public float fSignedDistance(in Vector3 p)
{
Vector3 q = Vector3.Abs(p-centre);
if (q.X>half || q.Y>half || q.Z>half) return half-MathF.Max(q.X,MathF.Max(q.Y,q.Z));
float x = q.X-half, y = q.Y-half, z = q.Z-half;
if (x>gap && y>gap && z>gap) return MathF.Max(x,y,z);
Vector3 w = new Vector3(MathF.Max(x+gap,0),MathF.Max(y+gap,0),MathF.Max(z+gap,0));
float h = MathF.Sqrt(MathF.Max(0,w.X*w.X+y*y+z*z-close*close));
return MathF.Max(MathF.Min(MathF.Min(x,y),z),h);
}
}
}
