static List<PicoGK.IImplicit> ReadPlanes(string path)
{
var planes=new List<PicoGK.IImplicit>();
foreach (var line in File.ReadLines(path).Skip(1))
{
var cells=line.Split(';');
if(cells.Length!=6) throw new InvalidDataException("malformed row");
if(cells.Any(x=>!double.TryParse(x,NumberStyles.Float,CultureInfo.InvariantCulture,out _))) throw new InvalidDataException("nonfinite cell");
double[] values=cells.Select(x=>double.Parse(x,NumberStyles.Float,CultureInfo.InvariantCulture)).ToArray();
Vector3 origin=new Vector3(-0.40000f,0.20000f,-0.60000f);
Vector3 normal=new Vector3((float)values[5],(float)values[3],(float)values[1]);
double distance=-Vector3.Dot(normal,origin);
planes.Add(new PicoGK.Plane(distance,normal));
}
if(!planes.Any()) throw new InvalidDataException("empty/sparse observation");
return planes;
}
