using System.Numerics;
using System.Globalization;
using System.Collections.Generic;
using System.Text.Json;
using PicoGK;
public static class Program
{
public static void Main(string[] arguments)
{
if (arguments.Length != 2) throw new ArgumentException("input output-directory");
if (Directory.Exists(arguments[1]) && Directory.EnumerateFileSystemEntries(arguments[1]).Any())
throw new IOException("Use an empty output directory.");
Directory.CreateDirectory(arguments[1]);
using PicoGK.Library lib = new PicoGK.Library(0.2f);
bool valid=true;
try { ReadXYZ(arguments[0]); }
catch(FormatException) { valid=false; }
catch(InvalidDataException) { valid=false; }
File.WriteAllText(Path.Combine(arguments[1],"refused.json"),JsonSerializer.Serialize(new {
status="needs_measurement",manufacturing_authorized=false,input_valid=valid,
missing=new[]{"calibrated_scanner_pixel_model","outward_sample_directions","camera_ray_origins"} }));
}
static List<Vector3> ReadXYZ(string path)
{
var points=new List<Vector3>();
foreach (string raw in File.ReadLines(path))
{
string line=raw.Trim();
if(line.Length==0 || line.StartsWith("#")) continue;
string[] cells=line.Split(new[]{',',';',' ','\t'},StringSplitOptions.RemoveEmptyEntries);
if(cells.Length!=3) throw new InvalidDataException("Exactly three coordinates required.");
float[] values=new float[3];
for(int j=0;j<3;j++)
if(!float.TryParse(cells[j],NumberStyles.Float,CultureInfo.InvariantCulture,out values[j])
|| !float.IsFinite(values[j]) || MathF.Abs(values[j])>8) throw new InvalidDataException("Finite bounded coordinates required.");
points.Add(new Vector3(values[0],values[1],values[2]));
}
if(points.Count==0) throw new InvalidDataException("No observations.");
return points;
}
public static void SaveArt(string output,PicoGK.Voxels body)
{
body.CalculateProperties(out float volume, out PicoGK.BBox3 measured);
if (!float.IsFinite(volume) || volume <= 0) throw new InvalidDataException("Empty body.");
body=Clean(new PicoGK.Mesh(body),body);
body.SaveToVdbFile(output);
}
public static PicoGK.Voxels Clean(PicoGK.Mesh raw,PicoGK.Voxels body)
{
using PicoGK.Library lib = new PicoGK.Library(body.Library.VoxelSize);
using PicoGK.Mesh clean = new PicoGK.Mesh(lib);
for (int i = 0; i < raw.nTriangleCount(); i++)
{
raw.GetTriangle(i, out Vector3 a, out Vector3 b, out Vector3 c);
double ux = (double)b.X-a.X, uy = (double)b.Y-a.Y, uz = (double)b.Z-a.Z;
double vx = (double)c.X-a.X, vy = (double)c.Y-a.Y, vz = (double)c.Z-a.Z;
if (uy*vz != uz*vy || uz*vx != ux*vz || ux*vy != uy*vx) clean.nAddTriangle(a,b,c);
}
return new PicoGK.Voxels(clean);
}
}
